messages.content:
Next issue: MCP. For web searching i'm using mcp-searxng-enhanced (https://github.com/OvertliDS/mcp-searxng-enhanced). Works great in other clients (Jan, Cherry, etc). In Rowboat it's failing:
```
{
  "serverName": "mcp-searxng-enhanced",
  "toolName": "search_web",
  "arguments": {}
}

{
  "success": true,
  "serverName": "mcp-searxng-enhanced",
  "toolName": "search_web",
  "result": {
    "content": [
      {
        "type": "text",
        "text": "Missing 'query' argument for search_web"
      }
    ],
    "isError": true
  },
  "message": "Successfully executed tool 'search_web' from server 'mcp-searxng-enhanced'"
}
```

Here's the full MCP configuration in Rowboat, jic:
```
{
  "mcpServers": {
    "firecrawl": {
      "command": "npx",
      "args": [
        "-y",
        "supergateway",
        "--stdio",
        "npx -y firecrawl-mcp"
      ],
      "env": {
        "FIRECRAWL_API_KEY": "x"
      }
    },
    "mcp-searxng-enhanced": {
      "command": "D:/llm/mcp-searxng-enhanced/.venv/Scripts/python.exe",
      "transport": "stdio",
      "args": [
        "D:/llm/mcp-searxng-enhanced/mcp_server.py"
      ],
      "env": {
        "SEARXNG_ENGINE_API_BASE_URL": "http://beelink:8080/search",
        "DESIRED_TIMEZONE": "America/Chicago"
      },
      "type": "stdio",
      "active": true
    },
    "test": {
      "url": "http://localhost:3000",
      "headers": {
        "Authorization": "Bearer test"
      }
    }
  }
}
```
